static const int XGB_ROOTS[220] = {0, 23, 46, 71, 94, 115, 140, 163, 194, 221, 246, 265, 292, 315, 340, 363, 386, 409, 436, 457, 478, 503, 524, 545, 562, 585, 600, 625, 648, 675, 700, 729, 752, 769, 790, 819, 842, 865, 886, 909, 932, 953, 978, 1001, 1026, 1051, 1078, 1103, 1130, 1151, 1170, 1193, 1214, 1241, 1260, 1289, 1318, 1337, 1362, 1387, 1412, 1437, 1458, 1483, 1506, 1529, 1558, 1581, 1604, 1621, 1638, 1655, 1670, 1689, 1716, 1739, 1762, 1787, 1816, 1829, 1850, 1867, 1892, 1921, 1950, 1973, 2000, 2021, 2038, 2059, 2082, 2107, 2124, 2145, 2174, 2195, 2220, 2239, 2266, 2295, 2318, 2335, 2364, 2379, 2408, 2421, 2448, 2471, 2500, 2517, 2534, 2565, 2594, 2617, 2634, 2659, 2676, 2693, 2710, 2731, 2752, 2769, 2786, 2811, 2832, 2857, 2872, 2887, 2904, 2927, 2944, 2975, 2998, 3027, 3040, 3055, 3076, 3105, 3122, 3137, 3156, 3183, 3206, 3235, 3260, 3271, 3288, 3319, 3336, 3351, 3370, 3391, 3422, 3439, 3454, 3477, 3508, 3539, 3568, 3593, 3610, 3631, 3658, 3673, 3686, 3705, 3736, 3755, 3774, 3793, 3814, 3845, 3862, 3875, 3886, 3901, 3920, 3939, 3956, 3973, 3994, 4025, 4042, 4073, 4090, 4101, 4112, 4131, 4156, 4183, 4202, 4225, 4240, 4271, 4296, 4311, 4336, 4355, 4376, 4387, 4418, 4439, 4462, 4489, 4516, 4541, 4572, 4587, 4606, 4627, 4650, 4663, 4674, 4695, 4714, 4735, 4754, 4775, 4788, 4817};
static const int XGB_TREE_COUNT = 220;
static const double XGB_BASE_MARGIN = 0.39999995791051124;

int milk_xgb_score(const double input[3], double output[2]) {
    if (input == NULL || output == NULL) return -1;
    for (int i = 0; i < 3; ++i) if (!isfinite(input[i])) return -2;
    double margin = XGB_BASE_MARGIN;
    for (int t = 0; t < XGB_TREE_COUNT; ++t) {
        int node = XGB_ROOTS[t];
        while (XGB_NODES[node].feature >= 0) {
            const XgbNode *n = &XGB_NODES[node];
            node = ((float)input[n->feature] < (float)n->threshold) ? n->left : n->right;
        }
        margin += XGB_NODES[node].value;
    }
    double p = 1.0 / (1.0 + exp(-margin));
    output[0] = 1.0 - p;
    output[1] = p;
    return 0;
}
